import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.filter.js";
import { API, graphqlOperation } from "aws-amplify";
import { get_awards_and_leaderboard } from "@/graphql/mutations";
export default {
  data() {
    return {
      searchQuery: "",
      showDialog: false,
      selectedEmployee: "",
      recentAwards: [],
      headers: [{
        title: "Rank",
        key: "rank"
      }, {
        title: "Employee Name",
        key: "winner_name"
      }, {
        title: "Total Awards",
        key: "total_awards"
      }],
      items: [],
      tableLoading: false,
      currentPage: 1,
      itemsPerPage: 10,
      windowHeight: 0
    };
  },
  computed: {
    filteredItems() {
      if (!this.searchQuery) return this.items;
      const q = this.searchQuery.toLowerCase();
      return this.items.filter(item => item.winner_user_id.toLowerCase().includes(q));
    },
    totalCount() {
      return this.filteredItems.length;
    },
    pageCount() {
      return Math.ceil(this.filteredItems.length / this.itemsPerPage);
    },
    paginatedItems() {
      const start = (this.currentPage - 1) * this.itemsPerPage;
      const end = start + this.itemsPerPage;
      return this.filteredItems.slice(start, end);
    },
    visiblePages() {
      const totalPages = this.pageCount;
      const current = this.currentPage;
      const delta = 2;
      let start = Math.max(1, current - delta);
      let end = Math.min(totalPages, current + delta);
      if (end - start < 4) {
        if (start === 1) {
          end = Math.min(totalPages, start + 4);
        } else {
          start = Math.max(1, end - 4);
        }
      }
      const pages = [];
      for (let i = start; i <= end; i++) {
        pages.push(i);
      }
      return pages;
    }
  },
  watch: {
    searchQuery() {
      this.currentPage = 1;
    },
    currentPage() {
      // Scroll to top when page changes
      const table = document.querySelector(".dtwidth");
      if (table) table.scrollIntoView({
        behavior: "smooth",
        block: "start"
      });
    }
  },
  async mounted() {
    this.windowHeight = window.innerHeight - 260;
    await this.fetchLeaderboard();
  },
  methods: {
    async fetchLeaderboard() {
      try {
        this.tableLoading = true;
        const input = {
          action_type: "GET_AWARDS_AND_LEADERBOARD"
        };
        const result = await API.graphql(graphqlOperation(get_awards_and_leaderboard, {
          input
        }));
        let response = JSON.parse(result.data.get_awards_and_leaderboard);
        // console.log(response);
        if (response.Status == "SUCCESS") {
          this.items = response.data.leaderboard || [];
        } else {
          this.items = [];
        }
        this.tableLoading = false;
      } catch (error) {
        this.tableLoading = false;
        console.error("Failed to fetch leaderboard:", error);
      }
    },
    showRecentAwards(click, value) {
      // console.log(value.item);
      this.selectedEmployee = value.item.winner_name;
      this.recentAwards = value.item.recent_awards || [];
      this.showDialog = true;
    }
  }
};
